mapper.sql:
SELECT o.id, o.order_no, o.product_code, o.product_name, o.product_color, o.recipe_code, o.recipe_name, o.planned_qty, o.batch_size, o.status, o.planned_start_date, o.planned_end_date, o.actual_start_time, o.actual_end_time, o.batch_count, COALESCE(b.total_batches, 0) as total_batches, COALESCE(b.completed_batches, 0) as completed_batches, COALESCE(b.qc_pass_batches, 0) as qc_pass_batches, COALESCE(b.total_actual_qty, 0) as total_actual_qty, COALESCE(b.total_in_stock_qty, 0) as total_in_stock_qty FROM mis_production_order o LEFT JOIN ( SELECT order_id, COUNT(*) as total_batches, SUM(CASE WHEN in_stock_status = '2' THEN 1 ELSE 0 END) as completed_batches, SUM(CASE WHEN qc_status = 'PASS' THEN 1 ELSE 0 END) as qc_pass_batches, SUM(actual_qty) as total_actual_qty, SUM(in_stock_qty) as total_in_stock_qty FROM mis_production_batch WHERE del_flag = '0' GROUP BY order_id ) b ON o.id = b.order_id WHERE o.del_flag = '0'
AND o.order_no LIKE CONCAT('%', #{params.orderNo}, '%')
AND o.product_code LIKE CONCAT('%', #{params.productCode}, '%')
AND o.product_name LIKE CONCAT('%', #{params.productName}, '%')
AND o.status = #{params.status}
AND o.planned_start_date >= #{params.beginDate}
AND o.planned_end_date <= #{params.endDate}
ORDER BY o.create_time DESC
